-- Self-contained Event Welcome bootstrap for GitHub Pages deployment.
-- Generated from V2/bottles.json: 300 physical RFID tags.
BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS beers (
  id BIGSERIAL PRIMARY KEY,
  bottle_num INT NOT NULL UNIQUE CHECK (bottle_num >= 1),
  giai TEXT NOT NULL UNIQUE,
  epc TEXT NOT NULL UNIQUE,
  url TEXT,
  welcome_batch_code TEXT NOT NULL DEFAULT 'rfid-batch-1'
);

ON CONFLICT (epc) DO UPDATE
  SET bottle_num = EXCLUDED.bottle_num,
      giai = EXCLUDED.giai,
      url = EXCLUDED.url,
      welcome_batch_code = EXCLUDED.welcome_batch_code;

CREATE INDEX IF NOT EXISTS beers_welcome_batch_number_idx
  ON beers(welcome_batch_code, bottle_num);

COMMIT;
